colors = list(map(int, input().split()))

# counts[i] will store number of intervals where color i is dominant
counts = [0] * (n + 1)

for i in range(n):
    freq = {}
    freq[colors[i]] = 1
    max_freq = 1
    dominant = colors[i]

    counts[dominant] += 1

    for j in range(i + 1, n):
        color = colors[j]
        freq[color] = freq.get(color, 0) + 1

        if freq[color] > max_freq:
            max_freq = freq[color]
            dominant = color
        elif freq[color] == max_freq:
            dominant = min(dominant, color)

        counts[dominant] += 1

for i in range(1, n + 1):
    print(counts[i], end=' ')
"}

