def solve():
    s = input().strip()
    MOD = 10**9 + 7

    # dp[i] = number of valid sequences ending at position i (0-indexed)
    dp = [0] * len(s)

    # First 'a'
    if s[0] == 'a':
        dp[0] = 1

    for i in range(1, len(s)):
        if s[i] == 'a':
            # Start new sequence with just this 'a'
            dp[i] = 1

            # Extend sequences from previous 'a's if there's at least one 'b' in between
            for j in range(i):
                if s[j] == 'a':
                    # Check if there's at least one 'b' between j and i
                    has_b = False
                    for k in range(j + 1, i):
                        if s[k] == 'b':
                            has_b = True
                            break

                    if has_b:
                        dp[i] = (dp[i] + dp[j]) % MOD

    total = sum(dp) % MOD
    print(total)

solve()
"}

