def count_valid_pairs(n, points):
    # Count pairs with same x-coordinate
    same_x = {}
    for x, y in points:
        if x not in same_x:
            same_x[x] = 0
        same_x[x] += 1
    same_x_pairs = sum(v * (v - 1) // 2 for v in same_x.values())

    # Count pairs with same y-coordinate
    same_y = {}
    for x, y in points:
        if y not in same_y:
            same_y[y] = 0
        same_y[y] += 1
    same_y_pairs = sum(v * (v - 1) // 2 for v in same_y.values())

    # Count identical pairs (same x and same y)
    identical = {}
    for x, y in points:
        key = (x, y)
        if key not in identical:
            identical[key] = 0
        identical[key] += 1
    identical_pairs = sum(v * (v - 1) // 2 for v in identical.values())

    # Total valid pairs = same_x_pairs + same_y_pairs - identical_pairs
    return same_x_pairs + same_y_pairs - identical_pairs

n = int(input())
points = []
for _ in range(n):
    x, y = map(int, input().split())
    points.append((x, y))

result = count_valid_pairs(n, points)
print(result)
"}

