import sys

def contains_boring(s, boring):
    """Check if string s contains any boring string"""
    for b in boring:
        if b in s:
            return True
    return False

def solve():
    s = sys.stdin.readline().strip()
    n = int(sys.stdin.readline())
    boring = []
    for _ in range(n):
        boring.append(sys.stdin.readline().strip())

    max_len = 0
    max_pos = 0

    # Try all starting positions
    for start in range(len(s)):
        # Try all possible lengths from this start position
        for length in range(1, len(s) - start + 1):
            end = start + length
            substr = s[start:end]

            # Check if this substring is valid
            if not contains_boring(substr, boring):
                # Update max if this is longer
                if length > max_len or (length == max_len and start < max_pos):
                    max_len = length
                    max_pos = start
            else:
                # Invalid substring, no longer valid
                break

    print(f"{max_len} {max_pos}")

if __name__ == "__main__":
    solve()
"}

