import sys

def solve():
    s = sys.stdin.readline().strip()
    n = int(sys.stdin.readline())
    boring = []
    for _ in range(n):
        boring.append(sys.stdin.readline().strip())

    max_len = 0
    max_pos = 0

    # Create a map from (start index, length) to boring string
    # Actually, just check for each starting position
    for start in range(len(s)):
        # Check if any boring string starts at this position
        valid = True
        for b in boring:
            if s[start:start+len(b)] == b:
                # This substring starts with a boring string
                valid = False
                break

        if not valid:
            continue

        # If valid, find the longest substring from this position
        # that doesn't contain any boring string
        end = start
        while end < len(s):
            # Check if any boring string ends at this position
            for b in boring:
                if end - len(b) + 1 >= 0 and s[end - len(b) + 1:end + 1] == b:
                    break
            else:
                # No boring string ends at this position
                end += 1
