import sys

def solve():
    s = sys.stdin.read().strip()

    # Try both protocols
    for protocol in ["http", "ftp"]:
        if s.startswith(protocol):
            remaining = s[len(protocol):]
            # Find "ru" in remaining
            idx = remaining.find("ru")
            if idx != -1:
                domain_part = remaining[:idx]
                context = remaining[idx+2:]

                # Check: domain_part non-empty (since protocol://<domain>.ru => domain non-empty)
                if domain_part:
                    # Construct answer
                    if context:
                        print(f"{protocol}://{domain_part}.ru/{context}")
                    else:
                        print(f"{protocol}://{domain_part}.ru")
                    return

    # This line should never be reached due to problem guarantee
    print(s)

if __name__ == "__main__":
    solve()
"}

