types = [0] * (2 * n + 1)  # 1-indexed
for i in range(1, 2 * n + 1):
    types[i] = 1 if (i % 2 == 1) else 2

# Check if this pattern works
valid = True
for i in range(1, 2 * n + 1):
    # Check 3 consecutive chairs
    for shift in [0, 1, 2]:
        pos1 = i + shift
        pos2 = i + shift + 1
        pos3 = i + shift + 2

        # Wrap around for chair 2n+1
        if pos1 > 2 * n:
            pos1 = 1
        if pos2 > 2 * n:
            pos2 = 1
        if pos3 > 2 * n:
            pos3 = 1

        t1 = types[pos1]
        t2 = types[pos2]
        t3 = types[pos3]

