import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    nonempty = sum(1 for x in a if x > 0)

    if nonempty > n/2:
        print("Alice")
    else:
        # If exactly n/2 nonempty, it's like a standard Nim game
        xor_sum = 0
        for x in a:
            xor_sum ^= x
        if xor_sum == 0:
            print("Bob")
        else:
            print("Alice")

if __name__ == "__main__":
    solve()
