import sys

def lowbit(x):
    return x & -x

def solve(sum_val, limit):
    # Try to build the set greedily from largest to smallest
    elements = []
    remaining = sum_val

    for num in range(limit, 0, -1):
        if remaining >= lowbit(num):
            elements.append(num)
            remaining -= lowbit(num)
            if remaining == 0:
                break

    if remaining == 0:
        return len(elements), elements
    else:
