def solve():
    s = input().strip()
    t = input().strip()

    n = len(s)
    m = len(t)

    # dp[i][j]: max occurrences using first i chars of s, currently at position j in t
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m + 1):
            # Current state: dp[i][j]
            # Option 1: Don't match s[i] with t[j]
            dp[i+1][j] = max(dp[i+1][j], dp[i][j])

            if j < m:
                # Option 2: Match s[i] with t[j]
                if s[i] == '?' or s[i] == t[j]:
                    # If we match, we go to position j+1
                    if j + 1 == m:
                        # We've completed a match of t
                        dp[i+1][j+1] = max(dp[i+1][j+1], dp[i][j] + 1)
                    else:
                        # Continue matching t
                        dp[i+1][j+1] = max(dp[i+1][j+1], dp[i][j])

    print(dp[n][0])

solve()
