import sys
from collections import defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        ceil_n = (n + 1) // 2
        ceil_m = (m + 1) // 2
        groups = defaultdict(list)
        for i in range(n):
            row_vals = [int(next(it)) for _ in range(m)]
            for j, val in enumerate(row_vals):
                row_idx = i + 1
                col_idx = j + 1
                if row_idx <= ceil_n:
                    min_row = row_idx
                else:
                    min_row = n - row_idx + 1
                if col_idx <= ceil_m:
                    min_col = col_idx
                else:
                    min_col = m - col_idx + 1
                key = (min_row, min_col)
                groups[key].append(val)
        total = 0
        for vals in groups.values():
            vals.sort()
            k = len(vals)
            if k % 2 == 1:
                target = vals[k // 2]
            else:
                target = vals[k // 2 - 1]
            cost = sum(abs(v - target) for v in vals)
            total += cost
        out_lines.append(str(total))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

