import sys

def count_occurrences(text, pattern):
    """Count the number of occurrences of pattern in text"""
    count = 0
    pattern_len = len(pattern)
    for i in range(len(text) - pattern_len + 1):
        if text[i:i+pattern_len] == pattern:
            count += 1
    return count

def solve():
    c = input().strip()
    s = input().strip()
    t = input().strip()

    # Try replacing each asterisk with each possible character and find the best result
    best_value = -float('inf')

    # For each possible replacement of asterisks, try all 26^num_asterisks possibilities
    # This is too many for large num_asterisks, but maybe we can do it greedily

    # Let's try all 26 possibilities for each asterisk independently
    # This might not be optimal, but let's see

    # Create a list of possible characters for each asterisk
    chars_for_asterisks = []
    for ch in 'abcdefghijklmnopqrstuvwxyz':
        chars_for_asterisks.append(ch)

    # Generate all combinations of characters for asterisks
    # This is too many (26^1000), but maybe we can do it more cleverly

    # Let's try a different approach: we'll try each possible character for each asterisk
    # and keep track of the best result for each partial string

    # Initialize with the original string
    dp = {tuple(c): (0, 0)}  # (s_count, t_count)

    for i in range(len(c)):
        if c[i] == '*':
            new_dp = {}
            for state, (s_count, t_count) in dp.items():
                # Try each possible character for this asterisk
                for ch in 'abcdefghijklmnopqrstuvwxyz':
                    # Update the state
                    new_state = list(state)
                    new_state[i] = ch
                    new_state = tuple(new_state)

                    # Compute the new s_count and t_count
                    new_s_count = s_count
                    new_t_count = t_count

                    # For each position that could be the start of s or t, check if the pattern matches
                    # Only check patterns that end at position i
                    for pattern, pattern_len in [(s, len(s)), (t, len(t))]:
                        for start in range(i - pattern_len + 1, i + 1):
                            if start < 0:
                                continue
                            match = True
                            for j in range(pattern_len):
                                if new_state[start + j] != pattern[j]:
                                    match = False
                                    break
                            if match:
                                if pattern == s:
                                    new_s_count += 1
                                else:
                                    new_t_count += 1

                    # Update dp
                    if new_state not in new_dp:
                        new_dp[new_state] = (new_s_count, new_t_count)
                    else:
                        best_s, best_t = new_dp[new_state]
                        if new_s_count > best_s or (new_s_count == best_s and new_t_count < best_t):
                            new_dp[new_state] = (new_s_count, new_t_count)

            dp = new_dp

    best_result = -float('inf')
    for (s_count, t_count) in dp.values():
        best_result = max(best_result, s_count - t_count)

    print(best_result)

