import sys
from collections import defaultdict, deque

def is_lucky(w):
    """Check if a number is lucky (digits only 4 and 7)."""
    s = str(w)
    return all(c in '47' for c in s)

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))

    # Build adjacency list with edge weights
    adj = defaultdict(list)
    for _ in range(n - 1):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Build graph using only non-lucky edges
    non_lucky_adj = defaultdict(list)
    for u in adj:
        for v, w in adj[u]:
            if not is_lucky(w):
                non_lucky_adj[u].append(v)
                non_lucky_adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    component_size = [0] * (n + 1)

    def bfs(start):
        """BFS to find component size starting from start."""
        queue = deque([start])
        visited[start] = True
        size = 1

        while queue:
            u = queue.popleft()
            for v in non_lucky_adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
