n = len(s)
m = len(t)

def can_place(i):
    """Check if we can place t starting at position i"""
    for j in range(m):
        if s[i+j] != '?' and s[i+j] != t[j]:
            return False
    return True

# Dynamic programming
# dp[i] = maximum number of placements starting from position i
dp = [0] * (n + 1)

def max_placements(i):
    if i > n - m:
        return 0

    if dp[i] != 0:
        return dp[i]

    if can_place(i):
        # Place t at position i
        res = 1 + max_placements(i + m)
    else:
        # Skip position i
        res = max_placements(i + 1)

    dp[i] = res
    return res

print(max_placements(0))
