    possible_values = []
    for num in a:
        val0 = num
        val1 = num & x
        possible_values.append((val0, val1))

    # For each possible value, find the minimum operations needed
    min_ops = float('inf')

    # For each possible value that can be achieved
    for i in range(n):
        val0, val1 = possible_values[i]

        # Check if this value can be achieved by at least two elements
        freq0 = 0  # count of elements that can achieve it with 0 ops
        freq1 = 0  # count of elements that can achieve it with 1 op

        for j in range(n):
            v0, v1 = possible_values[j]
            if v0 == val0:
                freq0 += 1
            if v1 == val0:
