import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = data[2:2+n*m]
    grid = [grid[i*m:(i+1)*m] for i in range(n)]

    # Find which letters are kept
    keep = [[True for _ in range(m)] for _ in range(n)]

    # Check rows
    for i in range(n):
        seen = {}
        for j in range(m):
            letter = grid[i][j]
            if letter in seen:
                seen[letter].append(j)
            else:
                seen[letter] = [j]

        for j in seen[letter]:
            if len(seen[letter]) > 1:
                for k in seen[letter]:
                    keep[i][k] = False

    # Check columns
    for j in range(m):
        seen = {}
        for i in range(n):
            letter = grid[i][j]
            if letter in seen:
                seen[letter].append(i)
            else:
                seen[letter] = [i]

        for i in seen[letter]:
            if len(seen[letter]) > 1:
                for k in seen[letter]:
                    keep[k][j] = False

    # Read remaining letters in order
    result = []
    for i in range(n):
        for j in range(m):
            if keep[i][j]:
                result.append(grid[i][j])

    print(''.join(result))

if __name__ == "__main__":
    solve()
