def is_ct(text):
    """Check if text is a correct text (CT)."""
    if '(' not in text and ')' not in text:
        return True  # Empty or whitespace only

    # Check if it's a valid balanced bracket sequence
    open_count = 0
    close_count = 0
    balance = 0
    valid_brackets = True
    for char in text:
        if char == '(':
            open_count += 1
            balance += 1
        elif char == ')':
            close_count += 1
            balance -= 1
        if balance < 0:
            valid_brackets = False
            break

    if not valid_brackets or open_count != close_count or balance != 0:
        return False

    # Check CT definition: first is '(', last is ')', and middle is CT
    if text[0] == '(' and text[-1] == ')':
        middle = text[1:-1]
        if is_ct(middle):
            return True

    # Check if it can be split into two consecutive CTs
    for i in range(1, len(text)):
        if is_ct(text[:i]) and is_ct(text[i:]):
            return True

    return False

def minimal_colors(text):
    """Return the minimal number of colors needed to color brackets.
    Nested pairs need different colors, non-nested can be same or different.
    This is equal to the maximum nesting depth plus 1 (1-indexed)."""
    if '(' not in text or ')' not in text:
        return 0  # No brackets needed

    depth = 0
    max_depth = 0
    balance = 0
    for char in text:
        if char == '(':
            balance += 1
            max_depth = max(max_depth, balance)
        elif char == ')':
            balance -= 1
    return max_depth + 1

