            line.append(cmd)
        else:
            line[cursor] = cmd

    # Check if current text is CT
    text = ''.join(line)
    if is_ct(text):
        result.append(minimal_colors(text))
    else:
        result.append(-1)

print(' '.join(map(str, result)))
