import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    # Separate items by weight
    items = [[] for _ in range(4)]  # index 0 unused
    for _ in range(n):
        w = int(data[idx]); idx += 1
        c = int(data[idx]); idx += 1
        items[w].append(c)

    # Sort each weight class by cost descending
    for w in range(1, 4):
        items[w].sort(reverse=True)

    # DP: dp[i] = max cost for weight i
    dp = [-1] * (m + 1)
    dp[0] = 0

    # Process weight 1 items
    for c in items[1]:
        for i in range(m, 0, -1):
            if dp[i - 1] != -1:
                dp[i] = max(dp[i], dp[i - 1] + c)

    # Process weight 2 items
    for c in items[2]:
        for i in range(m, 1, -1):
            if dp[i - 2] != -1:
                dp[i] = max(dp[i], dp[i - 2] + c)

    # Process weight 3 items
    for c in items[3]:
        for i in range(m, 2, -1):
            if dp[i - 3] != -1:
                dp[i] = max(dp[i], dp[i - 3] + c)

    # Find the maximum cost for any weight ≤ m
    result = max(dp[0:m + 1])
    print(result)

if __name__ == "__main__":
    solve()
"}

