import sys

def count_ways(n):
    """Count the number of ways for a given n"""
    ways = 0
    k = 2
    while True:
        ways_for_k = n // (k ** 3)
        if ways_for_k == 0:
            break
        ways += ways_for_k
        k += 1
    return ways

def solve():
    m = int(sys.stdin.readline())

    # Binary search for n
    low = 1
    high = 2
    while count_ways(high) < m:
        high *= 2

    # Binary search in [low, high]
    while low < high:
        mid = (low + high) // 2
        c = count_ways(mid)
        if c < m:
            low = mid + 1
        else:
            high = mid

    if count_ways(low) == m:
        return low
    return -1

print(solve())
"}

