import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    items = []
    for _ in range(n):
        w = int(next(it))
        c = int(next(it))
        items.append((w, c))

    # Sort items by weight
    items.sort()

    # Separate by weight
    items_by_weight = {}
    for w, c in items:
        if w not in items_by_weight:
            items_by_weight[w] = []
        items_by_weight[w].append(c)

    # Sort each weight group by cost descending
    for w in items_by_weight:
        items_by_weight[w].sort(reverse=True)

    # Count how many items of each weight
    count_1 = len(items_by_weight.get(1, []))
    count_2 = len(items_by_weight.get(2, []))
    count_3 = len(items_by_weight.get(3, []))

    # DP[i][j] = maximum cost with i items of weight 1 and j items of weight 2
    # We'll use a 1D DP array for the 2D state
    dp = [0] * (count_2 + 1)

    # Process items of weight 1
    for i in range(count_1 + 1):
        cost = 0
        if i > 0:
            cost = items_by_weight[1][i-1]

        # For each possible count of items of weight 2
        for j in range(count_2 + 1):
            # Check if we can use this state
            if i * 1 + j * 2 <= m:
                # Update dp[j]
                dp[j] = max(dp[j], cost + dp[j])

    # Process items of weight 2
    for j in range(count_2 + 1):
        cost = 0
        if j > 0:
            cost = items_by_weight[2][j-1]

        # For each possible count of items of weight 1
        for i in range(count_1 + 1):
            if i * 1 + j * 2 <= m:
                # Update dp[j]
                dp[j] = max(dp[j], cost + dp[j])

    # Process items of weight 3
    for k in range(count_3 + 1):
        cost = 0
        if k > 0:
            cost = items_by_weight[3][k-1]

        # For each possible combination of items of weight 1 and 2
        # We need to check if we can take k items of weight 3
        for j in range(count_2 + 1):
            for i in range(count_1 + 1):
                if i * 1 + j * 2 + k * 3 <= m:
                    # Update dp[j]
                    dp[j] = max(dp[j], cost + dp[j])

    print(max(dp))

if __name__ == "__main__":
    solve()
"}

