from collections import defaultdict, deque

def has_cycle(n, graph):
    """Check if graph has a cycle using iterative DFS"""
    visited = [False] * (n + 1)
    recursion_stack = [False] * (n + 1)
    stack = []

    def dfs(node):
        visited[node] = True
        recursion_stack[node] = True
        stack.append(node)

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor):
                    return True
            elif recursion_stack[neighbor]:
                return True

        recursion_stack[node] = False
        stack.pop()
        return False

    for node in range(1, n + 1):
        if not visited[node]:
            if dfs(node):
                return True
    return False

def count_topological_orderings(n, graph):
    """Count the number of topological orderings"""
    in_degree = [0] * (n + 1)
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    queue = deque([i for i in range(1, n + 1) if in_degree[i] == 0])
    count = 1

    while queue:
        count *= len(queue)
        next_queue = deque()
        for node in queue:
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    next_queue.append(neighbor)
        queue = next_queue

    return count

