from collections import defaultdict, deque

def is_unique_topological_sort(graph, n):
    in_degree = [0] * (n + 1)
    for u, v in graph.items():
        for neighbor in v:
            in_degree[neighbor] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    if len(queue) > 1:
        return False

    while queue:
        u = queue.popleft()

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

        if len(queue) > 1:
            return False

    return True

