    points = []

    idx = 1
    for _ in range(n):
        x = int(data[idx])
        y = int(data[idx + 1])
        points.append((x, y))
        idx += 2

    # Count pairs where x1 = x2 (regardless of y)
    x_count = {}
    for x, y in points:
        if x in x_count:
            x_count[x] += 1
        else:
            x_count[x] = 1

    pairs_x = 0
    for c in x_count.values():
        pairs_x += c * (c - 1) // 2

    # Count pairs where y1 = y2 (regardless of x)
    y_count = {}
    for x, y in points:
        if y in y_count:
            y_count[y] += 1
        else:
            y_count[y] = 1

    pairs_y = 0
    for c in y_count.values():
        pairs_y += c * (c - 1) // 2

    # Total pairs where x1=x2 OR y1=y2 = pairs_x + pairs_y - same_point_pairs
    # Same point pairs: for each (x,y) with count c, there are c*(c-1)//2 same points
    same_point_pairs = 0

    for x, y in points:
        # This counts pairs where x1=x2 AND y1=y2
        # But we need to be careful not to double count
        # Let me count same_point_pairs by iterating through points
        # and counting pairs (i, j) where i < j and points[i] == points[j]
        pass

    # Alternative: use a dictionary to count occurrences of each (x,y) pair
    position_count = {}
    for x, y in points:
        key = (x, y)
        if key in position_count:
