def digital_root(x):
    while x >= 10:
        x = sum(int(d) for d in str(x))
    return x

def is_billy_condition_hold(a, b):
    # Check if d(ab) == d(d(a)d(b))
    ab = a * b
    product_dr = digital_root(ab)
    dr_a = digital_root(a)
    dr_b = digital_root(b)
    product_of_dr = dr_a * dr_b
    product_of_dr_dr = digital_root(product_of_dr)
    return product_dr == product_of_dr_dr

N = int(input())

# Count triples where condition holds but ab != c
count = 0
for a in range(1, N + 1):
    for b in range(1, N + 1):
        if is_billy_condition_hold(a, b):
            # Check all c in [1, N] where ab != c
            for c in range(1, N + 1):
                if a * b != c:
                    count += 1

print(count)
"}

