points = []
for _ in range(3):
    x, y = map(int, input().split())
    points.append((x, y))

# Check if all three points are collinear (same vertical or horizontal line)
if (points[0][0] == points[1][0] and points[1][0] == points[2][0]) or \
   (points[0][1] == points[1][1] and points[1][1] == points[2][1]):
    print(1)
else:
    # Check if we can connect with 2 segments
    # We need a common point that is part of both segments
    # This means two pairs of points must share an x or y coordinate
    # And those pairs must share a common point

    # Check if there's a common point that can connect two lines
    found = False
    for i in range(3):
        for j in range(3):
            for k in range(3):
                if i != j and j != k and i != k:
                    # Check if (i,j) can be connected directly and (j,k) can be connected directly
                    # For direct connection, they need same x or y
                    x0, y0 = points[i]
                    x1, y1 = points[j]
                    x2, y2 = points[k]

                    if (x0 == x1 or y0 == y1) and (x1 == x2 or y1 == y2):
                        found = True
                        break
            if found:
                break
        if found:
            break

    if found:
        print(2)
    else:
        print(3)
"}

