def euler_phi(n):
    """Compute Euler's totient function φ(n)."""
    result = n
    i = 2
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        result -= result // n
    return result

def multiplicative_order(a, n):
    """Compute the multiplicative order of a modulo n."""
    if math.gcd(a, n) != 1:
        return None  # Not coprime

    # Euler's totient function
    phi = euler_phi(n)

    # Find the smallest d dividing phi such that a^d ≡ 1 (mod n)
    divisors = set()
    d = 1
    while d <= phi:
        if phi % d == 0:
            divisors.add(d)
        d += 1

    for d in sorted(divisors):
        if pow(a, d, n) == 1:
            return d
    return phi

def solve():
    m, x = map(int, input().split())

    # Number of cycles = (number of coprimes with m) / order(x modulo m) + 1
    phi = euler_phi(m)
    order = multiplicative_order(x, m)

    if order is None:
        print(phi + 1)
    else:
        print(phi // order + 1)

solve()
