def solve():
    n, x = map(int, input().split())
    a = list(map(int, input().split()))

    # For each element, list of values it can be in
    element_values = []
    for num in a:
        original = num
        reduced = num & x
        element_values.append((original, reduced))

    # Create a dictionary to count frequency of each value
    freq = {}
    for v1, v2 in element_values:
        freq[v1] = freq.get(v1, 0) + 1
        freq[v2] = freq.get(v2, 0) + 1

    # Find the value with at least two occurrences
    # and compute minimal operations
    min_ops = float('inf')
    for val in freq:
        # Count how many elements can reach this value with 0 operations
        zero_ops = sum(1 for v1, v2 in element_values if v1 == val)
        # Count how many elements can reach this value with 1 operation
        one_ops = sum(1 for v1, v2 in element_values if v2 == val)

        # We need at least 2 elements total
        if zero_ops + one_ops >= 2:
            # Choose the best combination
            if zero_ops >= 2:
                # Both elements can reach val with 0 operations
                ops = 0
            elif one_ops >= 2:
                # Both elements can reach val with 1 operation
                ops = 2
            else:
                # One element needs 0, one needs 1
                ops = 1

            if ops < min_ops:
                min_ops = ops

    if min_ops != float('inf'):
        print(min_ops)
    else:
        print(-1)

solve()
