    n = int(input())
    a = list(map(int, input().split()))

    # For each number, track its positions
    pos = {}
    for i, num in enumerate(a, 1):
        if num not in pos:
            pos[num] = []
        pos[num].append(i)

    # For each k, find the k-amazing number
    answer = []
    for k in range(1, n + 1):
        # We need a number that appears in all subsegments of length k
        # This means there exists a number that appears at positions i and i+k for all i
        min_amazing = -1

        # Check each candidate number
        for num, positions in pos.items():
            # Check if num appears at all required positions
            # Check if positions contain all i such that i+k <= n
            valid = True
            i = 1
            # Check positions 1, 1+k, 1+2k, ...
            while i + k <= n:
                # Check if there's an occurrence at position i
                found_i = False
                for p in positions:
                    if p == i:
                        found_i = True
                        break
                if not found_i:
                    valid = False
                    break
                # Check if there's an occurrence at position i+k
                found_i_plus_k = False
                for p in positions:
                    if p == i + k:
                        found_i_plus_k = True
                        break
                if not found_i_plus_k:
                    valid = False
                    break
                i += 1

            if valid:
                min_amazing = num
                break  # we want the minimum

        answer.append(str(min_amazing))

    print(' '.join(answer))
