    a = list(map(int, input().split()))

    answer = []

    for k in range(1, n + 1):
        # For each position i from 1 to n-k+1, collect the number at that position
        positions = []
        for i in range(1, n - k + 2):
            positions.append(a[i-1])  # 0-indexed array

        # Find the intersection of all these sets
        common = set(positions)
        for i in range(1, n - k + 1):
            common = common.intersection(set([a[i-1]]))

        if common:
            answer.append(str(min(common)))
        else:
            answer.append('-1')

    print(' '.join(answer))
