    n, m = len(s), len(t)

    # Precompute next_pos: next occurrence of each character from position i
    next_pos = [[-1] * 26 for _ in range(n)]
    for i in range(n-1, -1, -1):
        for c in range(26):
            if s[i] == chr(c + ord('a')):
                next_pos[i][c] = i
            else:
                next_pos[i][c] = next_pos[i+1][c] if i+1 < n else -1

    max_len = 0

    # For each possible start position of the removed substring
    for l in range(n):
        # Check if t is a subsequence of s[0:l]
        i = 0  # current position in t
        for j in range(l):
            if i < m and s[j] == t[i]:
                i += 1
        if i == m:
            # t is a subsequence of s[0:l], can we remove a longer substring?
            # Use binary search to find the maximum r >= l such that t remains a subsequence
            left, right = l, n-1
            best_r = l - 1

            while left <= right:
                mid = (left + right) // 2
                # Check if t is a subsequence of s[0:l] + s[mid+1:]
                j = 0  # current position in s
                k = 0  # current position in t
                while j < n:
