from collections import deque

def solve():
    n = int(input())
    h = list(map(int, input().split()))

    # We need to find the minimal number of discrete jumps from 1 to n
    # Create an adjacency list for discrete jumps
    graph = [[] for _ in range(n)]

    # Check from i to j for all i < j
    for i in range(n):
        for j in range(i + 1, n):
            # Check if jump from i to j is discrete
            if i + 1 == j:
                # Adjacent
                graph[i].append(j)
            else:
                # Check if all between are strictly less than both ends
                min_between = min(h[i+1:j])
                if min_between < min(h[i], h[j]) and h[i] < h[j]:
                    # Peak pattern
                    graph[i].append(j)
                # Check if all between are strictly greater than both ends
                max_between = max(h[i+1:j])
                if max_between > max(h[i], h[j]) and h[i] > h[j]:
                    # Valley pattern
                    graph[i].append(j)

    # BFS to find shortest path from 0 to n-1
    distances = [float('inf')] * n
    distances[0] = 0
    queue = deque([0])

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if distances[v] > distances[u] + 1:
                distances[v] = distances[u] + 1
                queue.append(v)

    print(distances[n-1])

if __name__ == "__main__":
    solve()
"}

