def ways(n):
    """Count the number of ways thieves can steal chocolates for a given n"""
    count = 0
    # k ranges from 2 to cube root of n
    max_k = int(n ** (1/3))
    for k in range(2, max_k + 1):
        # a can be from 1 to floor(n / (k^3))
        count += n // (k * k * k)
    return count

def find_n(m):
    """Find the smallest n such that ways(n) = m"""
    if m == 0:
        return -1

    n = 1
    while True:
        w = ways(n)
        if w == m:
            return n
        elif w > m:
            return -1
        n += 1

m = int(input())
print(find_n(m))
