def main():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    n = int(next(data))
    a, b, c, d = map(int, [next(data) for _ in range(4)])

    # Build tree
    tree = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        p = int(next(data))
        tree[p].append(i)
        tree[i].append(p)  # Undirected

    # Find which subtree of the root each office belongs to
    def find_subtree(root, target):
        # BFS to find the subtree of the root that contains target
        # Each subtree is defined by its root (child of the main root)
        for child in tree[root]:
            if child == root:
                continue  # Skip the root itself
            visited = set([root])
            stack = [child]
            visited.add(child)

            # BFS to find target in this subtree
            while stack:
                node = stack.pop()
                if node == target:
                    return child
                for neighbor in tree[node]:
                    if neighbor != root and neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)

    root = 1
    sub_a = find_subtree(root, a)
    sub_b = find_subtree(root, b)
    sub_c = find_subtree(root, c)
    sub_d = find_subtree(root, d)

    # Check if subtrees of a and b are identical
    def get_subtree_structure(root):
        # Base case: if no children, return empty tuple
        if not tree[root]:
            return ()

        children = [child for child in tree[root] if child != root]
        return tuple(get_subtree_structure(child) for child in children)

    # Get the structure of each subtree of the root
    root_children = [child for child in tree[root] if child != root]
    structures = {}
    for child in root_children:
        structures[child] = get_subtree_structure(child)

    # Check conditions
    condition1 = structures[sub_a] == structures[sub_b]
    condition2 = structures[sub_c] == structures[sub_d]

    if condition1 and condition2:
        print("YES")
    else:
        print("NO")

