import sys

def readints():
    return list(map(int, sys.stdin.readline().split()))

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def segments_intersect(a, b, c, d):
    # Check if segments ab and cd intersect
    ccw1 = cross(a, b, c) * cross(a, b, d)
    ccw2 = cross(c, d, a) * cross(c, d, b)

    if ccw1 < 0 and ccw2 < 0:
        return False

    if ccw1 == 0 and ccw2 == 0:
        # Check if they share a point
        if cross(a, b, c) == 0 and cross(a, b, d) == 0:
            return True
        return False

    if ccw1 < 0 or ccw2 < 0:
        return True

    return False

def point_on_segment(p, a, b):
    # Check if point p lies on segment ab
    return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
            min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

def same_side(p1, p2, line):
    # Check if p1 and p2 are on the same side of line
    return cross(line[0], line[1], p1) * cross(line[0], line[1], p2) >= 0

def reflect_point(p, line):
    # Reflect point p across line segment defined by points line[0] and line[1]
    a, b = line[0], line[1]
    ab = (b[0] - a[0], b[1] - a[1])
    ap = (p[0] - a[0], p[1] - a[1])

    dot = ap[0] * ab[0] + ap[1] * ab[1]
    dist_sq = ab[0] * ab[0] + ab[1] * ab[1]

    if dist_sq == 0:
        return p  # Line is a point

    proj = (dot / dist_sq) * ab[0], (dot / dist_sq) * ab[1]
    proj = (a[0] + proj[0], a[1] + proj[1])

    return (2 * proj[0] - p[0], 2 * proj[1] - p[1])

def main():
    xv, yv = readints()
    xp, yp = readints()
    xw1, yw1, xw2, yw2 = readints()
    xm1, ym1, xm2, ym2 = readints()

