    peter = (xp, yp)
    wall = ((xw1, yw1), (xw2, yw2))
    mirror = ((xm1, ym1), (xm2, ym2))

    # Check direct vision
    direct = not segments_intersect(victor, peter, wall[0], wall[1])

    if direct:
        # Check if mirror is just a point contact
        intersect = segments_intersect(victor, peter, mirror[0], mirror[1])
        if intersect:
            direct = False
        else:
            direct = True

    if direct:
        print("YES")
        return

    # Check reflection
    reflected_peter = reflect_point(peter, mirror)

    # Check if Victor and Peter are on the same side of the mirror
    if same_side(victor, peter, mirror):
        # Check if reflected vision path intersects wall
        if not segments_intersect(victor, reflected_peter, wall[0], wall[1]):
            print("YES")
        else:
            # Check if mirror is just a point contact
            intersect = segments_intersect(victor, reflected_peter, mirror[0], mirror[1])
            if intersect:
