import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    ai = [int(data[i]) for i in range(1, n + 1)]

    # Try all possible values for the smallest number (x1)
    for x1 in ai + [10**6 + 1]:
        # Try all possible values for the largest number (x4)
        for x4 in ai + [10**6 + 1]:

            # Check if x1 and x4 are distinct
            if x1 == x4:
                continue

            # x1 = M/2 and x4 = 3M/2
            # So M = 2x1 and 2x4/3
            if 2 * x1 != 2 * x4 / 3:
                continue
