            # The center of that 3x3 square must be unfilled

            # For a 3x3 square with center (i', j'), the cells on its border are:
            # (i'-1, j'), (i'+1, j'), (i', j'-1), (i', j'+1),
            # (i'-1, j'+1), (i'+1, j'+1), (i'-1, j'-1), (i'+1, j'-1)

            # So if (i, j) is on the border, then:
            # The center must be adjacent to (i, j) and within bounds

            # Possible centers for a border containing (i, j):
            centers = set([(i-1, j), (i+1, j), (i, j-1), (i, j+1),
                          (i-1, j-1), (i-1, j+1), (i+1, j-1), (i+1, j+1)])

            # Check if any center is valid (within bounds and unfilled)
            valid_center = False
            for c in centers:
