# Function to compute the count of paths that include y
def count_paths(y):
    if y == 1:
        return n  # 1 is always in all paths

    if y % 2 == 0:
        # y is even: any x >= y will eventually reach y
        lower = y
        upper = min(n, 2 * y - 1)
        return max(0, upper - lower + 1)
    else:
        # y is odd: numbers from y to 2y + 1 (or n) have y in their path
        lower = y
        upper = min(n, 2 * y + 1)
        return max(0, upper - lower + 1)

# Find the maximum y such that count_paths(y) >= k
# We'll use binary search on y (1 to n)
low = 1
high = n
result = 1

while low <= high:
    mid = (low + high) // 2

    if count_paths(mid) >= k:
        result = mid
        low = mid + 1  # Try for a larger y
    else:
        high = mid - 1  # Try for a smaller y

print(result)
