    # How much of t can we match using characters from s[0:start]
    t_idx = 0
    for i in range(start):
        if t_idx < len(t) and s[i] == t[t_idx]:
            t_idx += 1

    # Now we need to match t[t_idx:] using characters from s starting from some position > start
    if t_idx >= len(t):
        # Already matched all of t using prefix, we can remove everything after start
        max_length = max(max_length, len(s) - start)
        continue

    # Find the smallest end such that t[t_idx:] is a subsequence of s[end:]
    end = start
    t_ptr = t_idx
    while end < len(s):
        if s[end] == t[t_ptr]:
            t_ptr += 1
            if t_ptr >= len(t):
                break
        end += 1

    # The removed substring is from start to end-1, length = end - start
    if t_ptr >= len(t):
        max_length = max(max_length, end - start)

