def solve():
    s = input().strip()
    t = input().strip()

    n, m = len(s), len(t)

    # dp[i] = maximum number of occurrences up to position i
    dp = [0] * (n + 1)

    # Precompute positions where we can start t
    can_start = [False] * n
    for i in range(n - m + 1):
        match = True
        for j in range(m):
            if s[i + j] != '?' and s[i + j] != t[j]:
                match = False
                break
        if match:
            can_start[i] = True

    # DP
    for i in range(n):
        dp[i + 1] = dp[i]  # Continue without starting a new occurrence
        if can_start[i]:
            dp[i + m] = max(dp[i + m], dp[i] + 1)  # Start a new occurrence

    print(dp[n])

if __name__ == "__main__":
    solve()
