def get_max_digit(number_str):
    return max(int(d) for d in number_str)

def is_valid_base(number_str, p):
    return all(int(d) < p for d in number_str)

def convert_to_decimal(number_str, base):
    return int(number_str, base)

def convert_from_decimal(n, base):
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(str(n % base))
        n //= base
    return ''.join(reversed(digits))

def solve():
    a_str, b_str = input().split()

    max_digit = max(get_max_digit(a_str), get_max_digit(b_str))
    max_length = 0

    # Try all bases from max_digit + 2 up to 36 (bases go up to 36)
    for p in range(max_digit + 2, 37):
        if is_valid_base(a_str, p) and is_valid_base(b_str, p):
            # Convert to decimal
            a_dec = convert_to_decimal(a_str, p)
            b_dec = convert_to_decimal(b_str, p)

            # Add
            sum_dec = a_dec + b_dec

            # Convert back to base p
            sum_str = convert_from_decimal(sum_dec, p)

            # Update max length
            max_length = max(max_length, len(sum_str))

    print(max_length)

solve()
