{"code": "
import sys

def solve():
    m, x = map(int, sys.stdin.readline().split())

    # Room 0 is always a cycle by itself
    # Count cycles among rooms 1..m-1
    visited = set()
    cycles = 0

    for r in range(1, m):
        if r not in visited:
            cycles += 1
            curr = r
            while True:
                if curr in visited:
                    break
                visited.add(curr)
                curr = (curr * x) % m

    # We need to trap room 0, so +1
    return cycles + 1

if __name__ == "__main__":
    print(solve())
"}

