    for j in range(i + 1, n):
        if s[i] == s[j]:
            for k in range(j + 1, n):
                if s[j] == s[k]:
                    triples.append((i + 1, j + 1, k + 1))  # 1-indexed

# For each position r, find the minimum l such that there is a triple in [l, r]
# This means finding the minimum a where c <= r
min_l = n + 1  # Initialize to a value > n
result = 0

for r in range(n):
    # Check all triples where c = r + 1 (1-indexed)
    for a, b, c in triples:
        if c == r + 1:
            if a < min_l:
                min_l = a
    # If we found a triple with c <= r, then min_l is <= n
    if min_l <= n:
        result += min_l - 1

print(result)
