                    triples.append((i + 1, k + 1))  # (start, c)

# For each triple (start, c), the number of intervals containing it is
# (start) * (n - c + 1)
result = 0

for start, c in triples:
    # Count intervals [l, r] where l ≤ start and r ≥ c
    # This is: start * (n - c + 1)
    result += start * (n - c + 1)

