s = input().strip()
n = len(s)

# For each starting position i (1-indexed), find the minimum c such that
# there exists a triple with start = i and c (end) <= n
min_c_for_start = [n + 1] * (n + 1)  # 1-indexed

for i in range(n):
    for j in range(i + 1, n):
        if s[i] == s[j]:
            for k in range(j + 1, n):
                if s[j] == s[k]:
                    # triple at (i+1, j+1, k+1) -> start = i+1, end = k+1
                    start = i + 1
                    end = k + 1
                    if end < min_c_for_start[start]:
                        min_c_for_start[start] = end

# Now compute result
result = 0

for start in range(1, n + 1):
    if min_c_for_start[start] <= n:
        # Intervals starting at start: [start, min_c_for_start[start]] to [start, n]
        # That's (n - min_c_for_start[start] + 1) intervals
        result += n - min_c_for_start[start] + 1

print(result)
