def count_fixed_points(a):
    """Count the number of fixed points in the permutation."""
    count = 0
    for i, val in enumerate(a):
        if val == i:
            count += 1
    return count


def max_fixed_points_after_swap(a):
    """Find the maximum number of fixed points after at most one swap."""
    n = len(a)

    # Count current fixed points
    fixed = count_fixed_points(a)

    # Find all non-fixed elements
    non_fixed = [i for i in range(n) if a[i] != i]

    if not non_fixed:
        return fixed

    # Count number of 2-cycles
    two_cycle_count = 0
    for i in non_fixed:
        j = a[i]
        if j in non_fixed and a[j] == i:
            two_cycle_count += 1
            non_fixed.remove(i)
            non_fixed.remove(j)

    # Maximum fixed points = current fixed points + max(1, number of 2-cycles * 2)
    return fixed + max(1, two_cycle_count * 2)


