    if (p1[0] == p2[0] and p2[0] == p3[0]) or (p1[1] == p2[1] and p2[1] == p3[1]):
        return 1

    # Check if they can be connected with 2 segments
    # This means we need to check if there's a point that can act as a "corner"
    def is_right_angle(a, b, c):
        # Check if segments ab and bc form a right angle
        # ab is vertical if a[0] == b[0]
        # ab is horizontal if a[1] == b[1]
        # bc is vertical if b[0] == c[0]
        # bc is horizontal if b[1] == c[1]

        # ab vertical, bc horizontal
        if a[0] == b[0] and b[1] == c[1]:
            return True

        # ab horizontal, bc vertical
        if a[1] == b[1] and b[0] == c[0]:
            return True

        return False

    # Check if any two points can act as a pair for the right angle
    def can_form_right_angle(a, b, c):
        # a and b form one segment, c is the corner
        # Check if a-b is vertical and c-b is horizontal
        if a[0] == b[0] and b[0] == c[0]:
            return True  # All on same vertical line
        if a[1] == b[1] and b[1] == c[1]:
            return True  # All on same horizontal line

        # a and b form one segment, c is not the corner
        if a[0] == b[0] and b[1] == c[1]:
            return True
        if a[1] == b[1] and b[0] == c[0]:
            return True

        return False

    # Check all permutations
    if can_form_right_angle(p1, p2, p3):
