    # x is 0-indexed, k is the step size

    # We'll store triples as (start, length, value)
    # start is the 0-indexed starting position of the first character in the triple
    # length is 3k (length of the triple substring)
    triples = []

    for i in range(n):
        for k in range(1, n // 2 + 1):
            j = i + k
            if j + k >= n:
                break
            if s[i] == s[j] == s[j + k]:
                # Triple at positions i, j, j+k
                start = i
                length = 3 * k
                value = s[i]
                triples.append((start, length, value))

    # For each triple, find how many intervals [l, r] contain it
    # l can be from 1 to start + 1 (1-indexed)
    # r can be from start + length to n

    # But wait! This counts intervals containing multiple triples multiple times
    # So we need to count unique intervals that contain at least one triple

    intervals = set()
    for start, length, _ in triples:
        # Intervals that start <= start and end >= start + length
        for l in range(1, start + 2):
            for r in range(start + length, n + 1):
                intervals.add((l, r))

    # Also, intervals that start <= start + k and end >= start + 2k
