import sys

def lowbit(x):
    """Return the rightmost 1 bit of x."""
    return x & -x

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    sum_val = int(data[0])
    limit = int(data[1])

    # Calculate lowbit for each number from 1 to limit
    lowbits = [(lowbit(i), i) for i in range(1, limit + 1)]

    # Sort by lowbit in descending order
    lowbits.sort(reverse=True, key=lambda x: x[0])

    selected = []
    remaining = sum_val

    for lb, num in lowbits:
        if remaining <= 0:
            break
        if lb <= remaining:
            selected.append(num)
            remaining -= lb

    if remaining == 0:
        print(len(selected))
        print(' '.join(map(str, selected)))
    else:
        print(-1)

if __name__ == "__main__":
    solve()
