def solve():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    cache = set()
    cost = 0

    for i in range(n):
        current = a[i]
        if current in cache:
            continue
        cost += 1
        if len(cache) < k:
            cache.add(current)
        else:
            farthest_next = -1
            farthest_book = None
            for book in cache:
                next_idx = i + 1
                while next_idx < n and a[next_idx] != book:
                    next_idx += 1
                next_use = next_idx if next_idx < n else n
                if next_use > farthest_next:
                    farthest_next = next_use
                    farthest_book = book
            cache.remove(farthest_book)
            cache.add(current)
    print(cost)

if __name__ == "__main__":
    solve()
