def optimal_caching(n, k, requests):
    """Calculate the minimum cost using Belady's algorithm (farthest-in-future)."""
    library = set()
    cost = 0

    for i, book in enumerate(requests):
        if book not in library:
            cost += 1
            if len(library) == k:
                # Find the book in library that is farthest in the future (or never needed again)
                farthest = -1
                book_to_evict = None

                for candidate in library:
                    # Find the next occurrence of this candidate
                    next_use = -1
                    for j in range(i + 1, n):
                        if requests[j] == candidate:
                            next_use = j
                            break

                    if next_use == -1:
                        # This book is not needed again
                        book_to_evict = candidate
                        break
                    elif next_use > farthest:
                        farthest = next_use
                        book_to_evict = candidate

                library.remove(book_to_evict)

            library.add(book)

    return cost

n, k = map(int, input().split())
requests = list(map(int, input().split()))
print(optimal_caching(n, k, requests))
